<?php defined('RUETHIES_ADMIN') or die('Langsung tidak diizinkan.'); ?>
<?php if(!$scheduleEditor): ?>
<section class="card" id="schedule-list"><div class="list-caption"><h2>Jadwal PO</h2><?php if(is_owner($me)): ?><a class="btn" href="<?= h(po_admin_url('jadwal',['edit'=>'new'])) ?>">Tambah jadwal</a><?php endif; ?></div><p class="sub">Atur kapan pengajuan dibuka, ditutup, dan waktu pengambilan. Jadwal manual menahan kuota selama 15 menit; jadwal demo hanya menahan kuota setelah dikonfirmasi.</p>
<?php if (!$slots): ?><p class="empty">Belum ada jadwal. Tambahkan jadwal pertama untuk mulai menerima pesanan.</p><?php endif; ?>
<?php foreach ($slots as $s): ?><div class="item"><div class="grow"><b><?= h($s['title']) ?></b><?php if (($s['flow_version'] ?? 'legacy') === 'manual_v1'): ?><span class="badge">Transfer manual</span><?php endif; ?><span class="badge"><?= po_slot_open($s) ? 'Sedang dibuka' : ((bool)$s['is_open'] ? 'Di luar waktu buka' : 'Ditutup admin') ?></span><br><small>Pengajuan <?= h(po_date((int)$s['opens_at'])) ?> – <?= h(po_date((int)$s['closes_at'])) ?><br>Ambil <?= h(po_date((int)$s['pickup_from'])) ?> – <?= h(po_date((int)$s['pickup_until'])) ?></small></div>
<div class="actions"><a class="btn ghost" href="<?= h(po_admin_url('produk',['slot'=>(int)$s['id']])) ?>">Kelola produk</a>
<?php if (is_owner($me)): ?><a class="btn ghost" href="<?= h(po_admin_url('jadwal',['slot'=>(int)$s['id'],'edit'=>1])) ?>">Ubah jadwal</a><form method="post"><input type="hidden" name="csrf" value="<?= h($csrf) ?>"><input type="hidden" name="action" value="toggle-slot"><input type="hidden" name="slot_id" value="<?= (int)$s['id'] ?>"><input type="hidden" name="is_open" value="<?= $s['is_open'] ? 0 : 1 ?>"><button class="ghost"><?= $s['is_open'] ? 'Tutup PO' : 'Buka PO' ?></button></form><?php endif; ?></div></div><?php endforeach; ?></section>

<?php endif; ?>
<?php if($scheduleEditor && is_owner($me)): ?><a class="backlink" href="<?= h(po_admin_url('jadwal')) ?>">← Semua jadwal</a><section class="card editor" id="schedule"><h2><?= $edit ? 'Ubah jadwal' : 'Buat jadwal baru' ?></h2><p class="sub">Semua waktu WIB. Setelah ada pesanan, tanggal tidak bisa diubah; buka/tutup tetap tersedia.</p>
<?php if($scheduleLocked): ?><p class="warn">Jadwal sudah memiliki pesanan. Buat jadwal baru untuk mengubah tanggal; buka/tutup tetap tersedia di daftar jadwal.</p><?php endif; ?>
<form method="post"><fieldset class="po-form-fields" <?= $scheduleLocked?'disabled':'' ?>><input type="hidden" name="csrf" value="<?= h($csrf) ?>"><input type="hidden" name="action" value="save-slot"><input type="hidden" name="id" value="<?= (int)($edit['id'] ?? 0) ?>">
<?php if (!$edit): ?><label>Jenis jadwal<select name="flow_version"><option value="legacy" <?= ($_POST['flow_version']??'legacy')==='legacy'?'selected':'' ?>>Demo pengajuan (tanpa pembayaran)</option><option value="manual_v1" <?= ($_POST['flow_version']??'legacy')==='manual_v1'?'selected':'' ?>>Transfer manual + invoice</option></select></label><?php else: ?><p class="sub">Jenis jadwal: <?= ($edit['flow_version'] ?? 'legacy') === 'manual_v1' ? 'Transfer manual + invoice' : 'Demo pengajuan tanpa pembayaran' ?>. Buat jadwal baru untuk menggunakan jenis berbeda.</p><?php endif; ?>
<label>Nama periode<input name="title" required minlength="3" maxlength="100" placeholder="PO Weekend — Sabtu" value="<?= h(is_string($_POST['title']??null)?$_POST['title']:($edit['title']??'')) ?>"></label>
<div class="fgrid"><label>Mulai menerima pengajuan<input type="datetime-local" name="opens_at" required value="<?= h(po_datetime_value($edit,'opens_at')) ?>"></label><label>Batas pengajuan<input type="datetime-local" name="closes_at" required value="<?= h(po_datetime_value($edit,'closes_at')) ?>"></label><label>Mulai pengambilan<input type="datetime-local" name="pickup_from" required value="<?= h(po_datetime_value($edit,'pickup_from')) ?>"></label><label>Selesai pengambilan<input type="datetime-local" name="pickup_until" required value="<?= h(po_datetime_value($edit,'pickup_until')) ?>"></label></div><button>Simpan jadwal</button></fieldset></form></section><?php endif; ?>
